document.addEventListener('DOMContentLoaded', function() {
    const importBtn = document.getElementById('importBtn');
    const importModal = document.getElementById('importModal');
    const importModalBackdrop = document.getElementById('importModalBackdrop');
    const itemsModal = document.getElementById('itemsModal');
    const itemsModalBackdrop = document.getElementById('itemsModalBackdrop');
    const accountCreationModal = document.getElementById('accountCreationModal');
    const accountCreationModalBackdrop = document.getElementById('accountCreationModalBackdrop');
    const loadingSpinner = document.getElementById('loadingSpinner');

    const stepFileUpload = document.getElementById('stepFileUpload');
    const stepColumnMapping = document.getElementById('stepColumnMapping');
    const stepPreview = document.getElementById('stepPreview');
    const mappingFooter = document.getElementById('mappingFooter');
    const previewFooter = document.getElementById('previewFooter');

    const fileUpload = document.getElementById('fileUpload');
    const nextToPreviewBtn = document.getElementById('nextToPreviewBtn');
    const backToMappingBtn = document.getElementById('backToMappingBtn');
    const cancelMappingBtn = document.getElementById('cancelMappingBtn');
    const cancelPreviewBtn = document.getElementById('cancelPreviewBtn');
    const confirmImportBtn = document.getElementById('confirmImportBtn');

    const closeItemsBtn = document.getElementById('closeItemsBtn');
    const applySelloutBtn = document.getElementById('applySelloutBtn');
    const applySelloutContainer = document.getElementById('applySelloutContainer');

    const confirmAccountBtn = document.getElementById('confirmAccountBtn');
    const declineAccountBtn = document.getElementById('declineAccountBtn');

    let currentStep = 'fileUpload';
    let currentReportStatus = '';

    function showModal(modal, backdrop) {
        modal.classList.remove('slds-hide');
        backdrop.classList.remove('slds-hide');
    }

    function hideModal(modal, backdrop) {
        modal.classList.add('slds-hide');
        backdrop.classList.add('slds-hide');
    }

    function showLoading() {
        loadingSpinner.classList.remove('slds-hide');
    }

    function hideLoading() {
        loadingSpinner.classList.add('slds-hide');
    }

    function showStep(step) {
        stepFileUpload.classList.add('slds-hide');
        stepColumnMapping.classList.add('slds-hide');
        stepPreview.classList.add('slds-hide');
        mappingFooter.classList.add('slds-hide');
        previewFooter.classList.add('slds-hide');

        if (step === 'fileUpload') {
            stepFileUpload.classList.remove('slds-hide');
        } else if (step === 'columnMapping') {
            stepColumnMapping.classList.remove('slds-hide');
            mappingFooter.classList.remove('slds-hide');
        } else if (step === 'preview') {
            stepPreview.classList.remove('slds-hide');
            previewFooter.classList.remove('slds-hide');
        }
        currentStep = step;
    }

    function resetImportWizard() {
        showStep('fileUpload');
        fileUpload.value = '';
    }

    function showToast(title, message, variant) {
        const toast = document.createElement('div');
        toast.className = `slds-notify slds-notify_toast slds-theme_${variant}`;
        toast.innerHTML = `
            <div class="slds-notify__content">
                <h2 class="slds-text-heading_small">${title}</h2>
                <p>${message}</p>
            </div>
        `;
        document.body.appendChild(toast);
        setTimeout(() => {
            document.body.removeChild(toast);
        }, 3000);
    }

    // Event Listeners
    importBtn.addEventListener('click', function() {
        showModal(importModal, importModalBackdrop);
        resetImportWizard();
    });

    fileUpload.addEventListener('change', function(event) {
        if (event.target.files.length > 0) {
            showLoading();
            setTimeout(() => {
                hideLoading();
                showStep('columnMapping');
                showToast('Success', 'File uploaded successfully', 'success');
            }, 1000);
        }
    });

    nextToPreviewBtn.addEventListener('click', function() {
        showStep('preview');
    });

    backToMappingBtn.addEventListener('click', function() {
        showStep('columnMapping');
    });

    cancelMappingBtn.addEventListener('click', function() {
        hideModal(importModal, importModalBackdrop);
    });

    cancelPreviewBtn.addEventListener('click', function() {
        hideModal(importModal, importModalBackdrop);
    });

    confirmImportBtn.addEventListener('click', function() {
        showLoading();
        setTimeout(() => {
            hideLoading();
            hideModal(importModal, importModalBackdrop);
            showToast('Success', 'Successfully imported 25 sellout items', 'success');
        }, 2000);
    });

    // View Items buttons
    document.querySelectorAll('[data-report-id]').forEach(button => {
        button.addEventListener('click', function() {
            currentReportStatus = this.dataset.reportStatus;
            if (currentReportStatus === 'Completed') {
                applySelloutContainer.classList.remove('slds-hide');
            } else {
                applySelloutContainer.classList.add('slds-hide');
            }
            showModal(itemsModal, itemsModalBackdrop);
        });
    });

    closeItemsBtn.addEventListener('click', function() {
        hideModal(itemsModal, itemsModalBackdrop);
    });

    applySelloutBtn.addEventListener('click', function() {
        showLoading();
        setTimeout(() => {
            hideLoading();
            showModal(accountCreationModal, accountCreationModalBackdrop);
        }, 1000);
    });

    confirmAccountBtn.addEventListener('click', function() {
        showLoading();
        setTimeout(() => {
            hideLoading();
            hideModal(accountCreationModal, accountCreationModalBackdrop);
            showToast('Success', 'Created 2 invoices with 5 line items', 'success');
        }, 1500);
    });

    declineAccountBtn.addEventListener('click', function() {
        hideModal(accountCreationModal, accountCreationModalBackdrop);
        showToast('Info', 'Account creation skipped', 'info');
    });

    // Close modals when clicking backdrop
    [importModalBackdrop, itemsModalBackdrop, accountCreationModalBackdrop].forEach(backdrop => {
        backdrop.addEventListener('click', function() {
            const modal = backdrop.previousElementSibling;
            hideModal(modal, backdrop);
        });
    });
});

preview_css:
.preview-container {
    max-height: 400px;
    overflow-y: auto;
    border: 1px solid #dddbda;
    border-radius: 0.25rem;
}

.slds-modal__container {
    min-width: 40rem;
}

.slds-modal_large .slds-modal__container {
    min-width: 60rem;
    max-width: 90%;
}

.slds-notify {
    position: fixed;
    top: 20px;
    right: 20px;
    z-index: 9999;
    padding: 1rem;
    border-radius: 0.25rem;
    color: white;
    min-width: 300px;
}

.slds-theme_success {
    background-color: #04844b;
}

.slds-theme_error {
    background-color: #c23934;
}

.slds-theme_info {
    background-color: #0176d3;
}

.slds-file-selector__body {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 2rem;
    border: 2px dashed #dddbda;
    border-radius: 0.25rem;
    background-color: #fafaf9;
    cursor: pointer;
}

.slds-file-selector__body:hover {
    border-color: #0176d3;
    background-color: #f3f3f3;
}

.slds-file-selector__input {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}
